import{_ as t,o,c as a,ag as n}from"./chunks/framework.B9unkguw.js";const u=JSON.parse('{"title":"계획 뷰 - 지오펜스","description":"","frontmatter":{},"headers":[],"relativePath":"ko/qgc-user-guide/plan_view/plan_geofence.md","filePath":"ko/qgc-user-guide/plan_view/plan_geofence.md"}'),l={name:"ko/qgc-user-guide/plan_view/plan_geofence.md"};function i(r,e,c,s,p,h){return o(),a("div",null,e[0]||(e[0]=[n('<h1 id="계획-뷰-지오펜스" tabindex="-1">계획 뷰 - 지오펜스 <a class="header-anchor" href="#계획-뷰-지오펜스" aria-label="Permalink to &quot;계획 뷰 - 지오펜스&quot;">​</a></h1><p>GeoFences를 사용하면 비행이 가능한 가상 영역 또는 비행이 <em>허용되지 않는</em> 가상 영역을 만들 수 있습니다. 또한 허용된 지역을 벗어나 비행하는 경우 취해야 할 조치를 설정할 수 있습니다.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p><em>QGroundControl</em> will not display the GeoFence options if they are not supported by the connected vehicle firmware.</p></div><h2 id="create-a-geofence" tabindex="-1">Create a GeoFence <a class="header-anchor" href="#create-a-geofence" aria-label="Permalink to &quot;Create a GeoFence&quot;">​</a></h2><p>지오펜스를 생성하려면:</p><ol><li><p>계획 뷰로 이동</p></li><li><p>Select the <strong>GeoFence</strong> layer using the <a href="./plan_view.html#layer_switcher">Layer Switcher</a> in the top-right area of the map (or expand the <strong>GeoFence</strong> section in the <a href="./plan_view.html#plan_editor_panel">Plan Editor Panel</a>)</p></li><li><p>Insert a circular or polygon region by pressing the <strong>Circular Fence</strong> or <strong>Polygon Fence</strong> button in the GeoFence section. 새로운 지역이 지도와 버튼 아래의 관련 울타리 목록에 추가됩니다.</p></li></ol><div class="tip custom-block"><p class="custom-block-title">TIP</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>버튼을 여러 번 눌러 여러 영역을 만들 수 있으므로 복잡한 지오펜스 정의를 생성할 수 있습니다.</p></div></div><ul><li><p>원형 영역:</p><ul><li>지도의 중앙 점을 드래그하여 지역을 이동</li><li>원의 가장자리에 있는 점을 드래그하여 원의 크기를 조정합니다(또는 펜스 패널에서 반경 값을 변경할 수 있음).</li></ul></li><li><p>:::</p><ul><li>채워진 점을 드래그하여 정점 이동</li><li>채워진 정점 사이의 선에서 &quot;채워지지 않은&quot; 점을 클릭하여 새 정점을 만듭니다.</li></ul></li></ul><ol><li>기본적으로 새 지역은 <em>포함</em> 영역으로 생성됩니다(차량은 지역 내에 있어야 함). 울타리 패널에서 연결된 <em>포함</em> 확인란을 선택 취소하여 차량이 이동할 수 없는 제외 구역으로 변경합니다.</li></ol><p>Depending on the firmware, the GeoFence section may also show fence parameters (e.g. breach action) and a <strong>Breach Return Point</strong> that the vehicle will fly to if it breaches the fence.</p><h2 id="지오펜스-편집-삭제" tabindex="-1">지오펜스 편집/삭제 <a class="header-anchor" href="#지오펜스-편집-삭제" aria-label="Permalink to &quot;지오펜스 편집/삭제&quot;">​</a></h2><p>You can select a GeoFence region to edit by selecting its <em>Edit</em> radio button in the GeoFence section. 그런 다음 이전 섹션에서 설명한 대로 지도에서 지역을 편집할 수 있습니다.</p><p>지역은 연결된 <strong>Del</strong> 버튼을 눌러 삭제할 수 있습니다.</p><h2 id="지오펜스-업로드" tabindex="-1">지오펜스 업로드 <a class="header-anchor" href="#지오펜스-업로드" aria-label="Permalink to &quot;지오펜스 업로드&quot;">​</a></h2><p>The GeoFence is uploaded along with the rest of the plan using the <strong>Upload</strong> button in the <a href="./plan_view.html#file">Plan Toolbar</a>.</p>',15)]))}const g=t(l,[["render",i]]);export{u as __pageData,g as default};
